using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json.Linq;
public static class AERefresh {
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved edit required");string r=Path.GetFullPath(Path.Combine(Application.dataPath,"../../..")),h=r+"/SourceAssets/F1_AbandonedCamouflage/",e="Assets/Afrer_Seconds/05.Model/Environment/1F/";AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var src=JArray.Parse(File.ReadAllText(h+"clean_source.json"));foreach(var group in src.GroupBy(q=>(string)q["asset"])){var mi=(ModelImporter)AssetImporter.GetAtPath(group.Key);mi.isReadable=false;mi.importNormals=ModelImporterNormals.Import;foreach(string n in group.SelectMany(q=>q["materials"]).Select(v=>(string)v).Distinct()){var mat=AssetDatabase.LoadAssetAtPath<Material>(e+"Materials/"+n+".mat");if(!mat)throw new Exception("Missing material "+n);mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),n),mat);}mi.SaveAndReimport();}
  foreach(var mf in GameObject.Find("1F_AbandonedFactory").GetComponentsInChildren<MeshFilter>())if(AssetDatabase.GetAssetPath(mf.sharedMesh).Contains("/AE_")){var mc=mf.GetComponent<MeshCollider>();if(mc){mc.sharedMesh=mf.sharedMesh;PrefabUtility.RecordPrefabInstancePropertyModifications(mc);}}
  Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(s);EditorSceneManager.OpenScene(s.path);return new{refreshed=src.Select(q=>(string)q["asset"]).Distinct().Count()};
 }
}
